// nuxt.config.ts
export default defineNuxtConfig({
  ssr: true,                      // 既定: SSR
  nitro: {
    prerender: {
      routes: ['/', '/about'],    // ビルド時に静的化
    },
  },
  routeRules: {
    '/admin/**': { ssr: false },  // /admin 配下は SPA
    '/blog/**': { isr: 60 },      // ISR: 60 秒キャッシュ
  },
})

export default defineNuxtConfig({
  routeRules: {
    '/': { prerender: true },
    '/blog/**': { isr: 60 },
    '/news/**': { swr: 30 },
    '/admin/**': { ssr: false },
  },
})

// MVP 段階の典型構成
export default defineNuxtConfig({
  ssr: true,
  routeRules: {
    '/': { prerender: true },
    '/about': { prerender: true },
    '/dashboard/**': { ssr: false },
  },
})
